:root {
  --teal: #0e5f5c;
  --teal-dark: #0a4542;
  --teal-light: #3a8a86;
  --amber: #e8a33d;
  --amber-dark: #b97f22;
  --ink: #12211f;
  --muted: #5a6b68;
  --paper: #f7f5f0;
  --card: #ffffff;
  --line: #dfe6e3;
  --red: #b3402e;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
